import pandas as pd
from collections import defaultdict

def strong_friendship(friendship: pd.DataFrame) -> pd.DataFrame:
    adj = defaultdict(set)
    for _, row in friendship.iterrows():
        u1, u2 = row['user1_id'], row['user2_id']
        adj[u1].add(u2)
        adj[u2].add(u1)

    res = []
    for _, row in friendship.iterrows():
        u1, u2 = row['user1_id'], row['user2_id']
        common = len(adj[u1].intersection(adj[u2]))
        if common >= 3:
            res.append({'user1_id': u1, 'user2_id': u2, 'common_friend': common})

    if not res:
        return pd.DataFrame(columns=['user1_id', 'user2_id', 'common_friend'])
    return pd.DataFrame(res)
